example.code:
var row = new AlarmRow
{
    Id = 1001,
    Time = DateTime.Now,
    Priority = AlarmPriority.Critical,
    Message = "취수 펌프 #2 과전류 트립",
    Source = "PLC1"
};

// 마크업
// <DvAlarmBanner items="{Alarms}" onack="Ack"/>
// <DvAlarmList items="{Alarms}" onack="Ack" grow="1"/>

public sealed class AlarmVm
{
    public AlarmLog Log { get; } = new(maxRows: 200);
    public IReadOnlyList<AlarmRow> Alarms => Log.Rows;
    public string UnAckedText => $"미확인 {Log.UnAckedCount}건";

    public void Ack(AlarmRow row) => Log.Ack(row.Id);   // 배너·목록의 확인 버튼
    public void AckAll() => Log.AckAll();               // 전체 확인 버튼(onclick)
    public void Trip() => Log.Raise(AlarmPriority.Critical, "취수 펌프 #2 과전류 트립", "PLC1");
}

var app = new DvApp { Theme = DvTheme.Dark };
app.Pages.Add(new HomePage());
app.Pages.Add(new MonitorPage());
app.Left = new MainSideBar();
app.HandlerError += (_, e) => Log.Error(e.Exception, $"{e.Kind} {e.Member}");
app.Show<HomePage>();

public partial class MainSideBar : DvBar
{
    public void ShowMonitor() => App.Show<MonitorPage>();
}

app.Left = new MainSideBar();

public partial class ConfirmDialog : DvDialog<bool?>
{
    public string Message { get; }
    public ConfirmDialog(string message) => Message = message;
    public void Ok() => Close(true);
    public void No() => Close(false);
}

bool? ok = await App.ShowDialog<ConfirmDialog, bool?>("삭제할까요?");

public partial class MonitorPage : DvPage
{
    public double Temperature { get; set; }
    public void Back() => App.Show<HomePage>();
    protected override void OnShown() { /* 보일 때 */ }
    protected override void OnHidden() { /* 숨겨질 때 */ }
}

using Devinno.UI; using Devinno.UI.Components;
var registry = new ComponentRegistry(); registry.Register(""" <DvComponent name="PumpCard"> <DvParam name="Title" default="-"/> <DvParam name="Run"/> <DvCard title="{Title}"> <DvToggle value="{Run}"/> <DvSlot/> </DvCard> </DvComponent> """);
// Run 에 {Bind …} 를 주면 토글 조작이 vm.Pump1.Running 에 기록된다 var surface = new DvSurface(""" <DvScreen> <PumpCard Title="펌프 1" Run="{Bind Pump1.Running}"> <DvLabel text="{Pump1.Flow}"/> </PumpCard> </DvScreen> """, vm, registry);

surface.HandlerError += (_, e) =>
    log.Error(e.Exception, $"{e.Kind} {e.Member} ({e.Tag}) 실패");
// 예: Kind = "onclick", Member = "Start", Tag = "DvButton", Exception = 처리기가 던진 InvalidOperationException

// 바이트로 받기 (테스트에서 비교 등)
byte[] png = DvRenderer.RenderToPng(markup, vm, 1280, 800);

// 파일로 저장 (밝은 테마)
DvRenderer.RenderToFile(markup, vm, 1280, 800, "screen.png", DvTheme.Light);

// 점멸 위젯의 다른 위상을 보려면 시각을 지정 (DvLamp 기본 점멸 주기 500ms)
DvRenderer.RenderToFile(markup, vm, 1280, 800, "blink-phase2.png", null, null, timestampMs: 500);

// 생성 (UI 스레드)
var surface = new DvSurface(markup, vm, DvTheme.Light);

// 그리기 — 호스트의 페인트 콜백에서
var now = Environment.TickCount64;
if (surface.NeedsRender)
    surface.RenderTo(canvas, width, height, now);
long? due = surface.NextAnimationDue(now); // 이 시각에 다시 그리도록 타이머 예약(null 이면 예약 없음)

// 입력 — 마우스/터치 이벤트에서 (캔버스 좌표)
surface.PointerDown(new SKPoint(x, y));
surface.PointerMove(new SKPoint(x, y));
surface.PointerUp(new SKPoint(x, y));
surface.PointerWheel(new SKPoint(x, y), 1f); // 위로 한 칸

// 가상 키보드 모드에서 물리 키보드 전달
surface.KeyInput(DvKey.Enter);
surface.TextInput("a");

// VM 이 바뀜 (다른 스레드에서도 가능) — 그다음 호스트 렌더 루프를 깨운다
surface.Invalidate();

var surface = new DvSurface(markup, vm);
surface.HandlerError += (_, e) =>
    Log.Error(e.Exception, $"화면 처리기 실패: {e.Kind} {e.Member} ({e.Tag})");
// VM 의 public void Start() 가 예외를 던지면 → Kind = "onclick", Member = "Start", Tag = "DvButton"

using Devinno.UI.Layout;
using Devinno.UI.Markup;

var root = MarkupParser.Parse("<DvRow><DvButton text=\"시작\"/><DvButton text=\"정지\"/></DvRow>");
LayoutBox tree = new LayoutEngine().Layout(root, vm: null, width: 800, height: 480);
foreach (var b in tree.Children)
    Console.WriteLine($"{b.ResolvedText}: {b.Rect}");

using Devinno.UI.Layout;
using Devinno.UI.Markup;

