strings.LoadJson("ko", "{\"pump\":\"펌프\",\"alarm\":{\"none\":\"알람 없음\"}}");
strings.LoadJson("en", "{\"pump\":\"Pump\",\"alarm\":{\"none\":\"No alarms\"}}");
surface.Strings = strings;   // 마크업: <DvLabel text="@pump"/>, <DvLabel text="{L10n.alarm.none}"/>
strings.Language = "en";     // 붙은 화면이 영어로 다시 그려짐

using Devinno.UI.Markup;

try
{
    var root = MarkupParser.Parse("<DvStack><DvLabel text=\"{Title}\"/></DvStack>");
    Console.WriteLine($"{root.Tag}, 자식 {root.Children.Count}개"); // DvStack, 자식 1개
}
catch (System.Xml.XmlException ex)
{
    Console.WriteLine($"마크업 오류 {ex.LineNumber}:{ex.LinePosition} {ex.Message}");
}

