// 마크업
// <DvTrend source="{Trend}" window="120" area="true">
//   <DvTrendChannel name="temp" label="온도" unit="C" color="#22d3ee"/>
//   <DvTrendChannel name="press" label="압력" unit="bar"/>
// </DvTrend>

public sealed class TrendVm
{
    public TrendBuffer Trend { get; } = new(capacity: 2000);
}

// 폴링 스레드(예: System.Threading.Timer 콜백). vm = TrendVm, window = 화면을 띄운 ViewWindow
var now = DateTime.Now;
vm.Trend.Add("temp", now, 62.4);
vm.Trend.AddRange("press", new[] { new TrendPoint(now.AddMilliseconds(-500), 41.0), new TrendPoint(now, 41.3) });
window.Invalidate();   // WinForms 는 viewControl.MarkUpdated()

var (lo, hi, step) = TrendScale.Nice(3.7, 96.2);          // (0, 100, 20)
var ticks = ScaleTicks.Values(lo, hi, step);              // 0, 20, 40, 60, 80, 100
var timeStep = TrendScale.TimeStep(120);                  // 30 (초)
var label = TrendScale.TimeLabel(DateTime.Now, timeStep); // "HH:mm:ss"

var pts = new List<SKPoint> { new(0, 80), new(40, 20), new(80, 20), new(120, 60) };
using var path = TrendPath.Build(pts, smooth: true);
using var paint = new SKPaint { IsAntialias = true, Style = SKPaintStyle.Stroke, StrokeWidth = 2, Color = SKColors.DeepSkyBlue };
canvas.DrawPath(path, paint);

public class LogVm
{
    public string Mode { get; set; } = Values.GridSelectionMode.Multi;   // <DvDataGrid selection-mode="{Mode}">
    public string PickMode { get; set; } = Values.DateTimeMode.Date;      // <DvDateTimeInput mode="{PickMode}"/>
}

public sealed class BatteryGauge : DvWidget
{
    public override SKSize Measure(DvWidgetContext ctx, float? availableWidth) => new(160, 60);

    public override void Paint(SKCanvas canvas, SKRect bounds, DvWidgetContext ctx)
    {
        var soc = Math.Clamp(ctx.Number("value", 0), 0, 100);
        using var track = new SKPaint { IsAntialias = true, Color = ctx.Color("gauge-track") };
        using var fill = new SKPaint { IsAntialias = true, Color = ctx.Color(soc < 20 ? "tone-danger" : "tone-success") };
        canvas.DrawRoundRect(bounds, 6, 6, track);
        canvas.DrawRoundRect(new SKRect(bounds.Left, bounds.Top, bounds.Left + bounds.Width * (float)soc / 100, bounds.Bottom), 6, 6, fill);
    }
}

registry.RegisterWidget<BatteryGauge>("BatteryGauge");
// markup: <BatteryGauge value="{Soc}"/>
